hl.config({
    input = {
        kb_layout  = "latam",
        kb_variant = "",
        kb_model   = "",
        kb_options = "",
        kb_rules   = "",

        follow_mouse = 1,

        sensitivity = 0.3, -- -1.0 - 1.0, 0 means no modification.

        touchpad = {
            natural_scroll = true,
        },
    },
})

hl.gesture({
    fingers = 3,
    direction = "horizontal",
    action = "workspace"
})
hl.gesture({
    fingers = 4,
    direction = "right",
    action = function () rofi_menu_anim_global("~/.config/WallpaperSelector/wallpaper.sh") end
})
hl.gesture({
    fingers = 4,
    direction = "left",
    action = function() toggle_ags_widget_anim("slide right", "toggle") end
})
hl.gesture({
    fingers = 3,
    direction = "vertical",
    action = function () rofi_menu_anim("slide bottom", "rofi -show drun") end
})

